// Import necessary React hooks and components
import React, { useState } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import Navbar from "../Components/Navbar"; // Component for the navigation bar
import Footer from "../Components/Footer"; // Component for the footer
import "../styles/UserPages.css"; // Import CSS styling
import API_BASE_URL from "../config"; // Base URL for API requests

// Functional component for subscription checkout process
const SubscriptionCheckout = () => {
  // Hooks to navigate programmatically and access state from routing
  const navigate = useNavigate();
  const location = useLocation();
  const { planName } = location.state || {};

  // State to manage shipping information form inputs
  const [shippingInfo, setShippingInfo] = useState({
    fullName: "",
    address: "",
    city: "",
    state: "",
    zip: "",
    country: "USA",
  });

  // Retrieve user ID from session storage
  const userId = sessionStorage.getItem("userId");

  // Handler function to update shipping info state on input change
  const handleChange = (e) => {
    setShippingInfo({ ...shippingInfo, [e.target.name]: e.target.value });
  };

  // Handler function for form submission to process subscription
  const handleSubmit = async (e) => {
    e.preventDefault();
  
    if (!planName) {
      alert("Missing plan information. Please select a subscription plan first.");
      return navigate("/business-plans");
    }
  
    
    let planPrice = 0;
    if (planName === "Starter") planPrice = 19;
    else if (planName === "Fitness Plus") planPrice = 39;
    else if (planName === "Strength Max") planPrice = 69;
    else if (planName === "Elite Home Gym") planPrice = 99;
  
    try {
      const estimatedDelivery = new Date();
      estimatedDelivery.setDate(estimatedDelivery.getDate() + Math.floor(Math.random() * 5) + 3);
  
      await fetch(`${API_BASE_URL}/api/subscriptions`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          userId,
          planName,
          planPrice,            
          shippingInfo,
          estimatedDelivery,
        }),
      });
  
      navigate("/subscription-confirmed");
    } catch (err) {
      console.error("Error subscribing:", err);
      alert("Failed to complete subscription.");
    }
  };
  

  // JSX rendering the subscription checkout form
  return (
    <div>
      <Navbar />
      <div className="page-wrapper">
        <h2 className="page-title">🏋️ Subscription Checkout</h2>
        <p className="page-subtitle">Complete your shipping information to confirm your plan!</p>

        {/* Form to collect shipping information for subscription checkout */}
        <form onSubmit={handleSubmit} className="checkout-form">
          <input 
            type="text" 
            name="fullName" 
            placeholder="Full Name" 
            value={shippingInfo.fullName}
            onChange={handleChange}
            required
          />
          <input 
            type="text" 
            name="address" 
            placeholder="Address" 
            value={shippingInfo.address}
            onChange={handleChange}
            required
          />
          <input 
            type="text" 
            name="city" 
            placeholder="City" 
            value={shippingInfo.city}
            onChange={handleChange}
            required
          />
          <input 
            type="text" 
            name="state" 
            placeholder="State" 
            value={shippingInfo.state}
            onChange={handleChange}
            required
          />
          <input 
            type="text" 
            name="zip" 
            placeholder="ZIP Code" 
            value={shippingInfo.zip}
            onChange={handleChange}
            required
          />
          <button type="submit" className="subscribe-btn">
            Confirm Subscription
          </button>
        </form>
      </div>
      <Footer />
    </div>
  );
};

// Export component for use in other parts of the application
export default SubscriptionCheckout;
